-- Module: hr — Workforce / HR

CREATE SCHEMA IF NOT EXISTS hr;
COMMENT ON SCHEMA hr IS 'Workforce / HR: Staff records, designations, departments, subject competencies, leave types and leave applications.';

CREATE TABLE hr.designation (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    code varchar(60) NOT NULL,
    name varchar(120) NOT NULL,
    staff_category varchar(30) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    sort_order integer NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true,
    CONSTRAINT pk_designation PRIMARY KEY (id),
    CONSTRAINT ck_designation_staff_category CHECK (staff_category IN ('teaching', 'non_teaching')),
    CONSTRAINT uq_designation_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE hr.designation IS 'Staff designation catalogue (Principal, Teacher, Accountant, Driver...).';
COMMENT ON COLUMN hr.designation.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN hr.designation.tenant_id IS 'Owning tenant (customer organisation). Platform defaults are copied into each tenant at provisioning. Row-level security key.';
COMMENT ON COLUMN hr.designation.code IS 'Designation code.';
COMMENT ON COLUMN hr.designation.name IS 'Designation name.';
COMMENT ON COLUMN hr.designation.staff_category IS 'Teaching or non-teaching.';
COMMENT ON COLUMN hr.designation.created_at IS 'Row creation time.';
COMMENT ON COLUMN hr.designation.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN hr.designation.updated_at IS 'Last update time.';
COMMENT ON COLUMN hr.designation.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN hr.designation.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN hr.designation.row_version IS 'Optimistic-locking version.';
COMMENT ON COLUMN hr.designation.sort_order IS 'Display order.';
COMMENT ON COLUMN hr.designation.is_active IS 'Whether offered for new picks.';

CREATE TABLE hr.staff (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    person_id uuid NOT NULL,
    user_id uuid,
    institution_id uuid NOT NULL,
    employee_code varchar(30),
    designation_id uuid,
    sub_designation varchar(120),
    employment_type varchar(30) NOT NULL DEFAULT  'full_time',
    joining_date date,
    reporting_to_staff_id uuid,
    primary_department_id uuid,
    highest_qualification_id uuid,
    qualification_detail varchar(150),
    specialization varchar(150),
    interests text,
    max_periods_per_week integer,
    status varchar(30) NOT NULL DEFAULT  'active',
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_staff PRIMARY KEY (id),
    CONSTRAINT ck_staff_employment_type CHECK (employment_type IN ('full_time', 'part_time', 'contract', 'visiting')),
    CONSTRAINT ck_staff_status CHECK (status IN ('active', 'inactive', 'exited')),
    CONSTRAINT uq_staff_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE hr.staff IS 'Employee / faculty member of an institution.';
COMMENT ON COLUMN hr.staff.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN hr.staff.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN hr.staff.person_id IS 'Person.';
COMMENT ON COLUMN hr.staff.user_id IS 'Staff login account.';
COMMENT ON COLUMN hr.staff.institution_id IS 'Employing institution.';
COMMENT ON COLUMN hr.staff.employee_code IS 'Employee number.';
COMMENT ON COLUMN hr.staff.designation_id IS 'Designation.';
