COMMENT ON COLUMN hr.staff.employment_type IS 'Employment type.';
COMMENT ON COLUMN hr.staff.joining_date IS 'Date of joining.';
COMMENT ON COLUMN hr.staff.reporting_to_staff_id IS 'Manager this staff member reports to (another hr.staff row).';
COMMENT ON COLUMN hr.staff.primary_department_id IS 'Main department.';
COMMENT ON COLUMN hr.staff.highest_qualification_id IS 'Highest qualification.';
COMMENT ON COLUMN hr.staff.qualification_detail IS 'Qualification detail.';
COMMENT ON COLUMN hr.staff.specialization IS 'Specialisation.';
COMMENT ON COLUMN hr.staff.interests IS 'Interests / extra responsibilities.';
COMMENT ON COLUMN hr.staff.max_periods_per_week IS 'Teaching-load ceiling in periods.';
COMMENT ON COLUMN hr.staff.status IS 'Employment state.';
COMMENT ON COLUMN hr.staff.created_at IS 'Row creation time.';
COMMENT ON COLUMN hr.staff.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN hr.staff.updated_at IS 'Last update time.';
COMMENT ON COLUMN hr.staff.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN hr.staff.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN hr.staff.row_version IS 'Optimistic-locking version.';
CREATE UNIQUE INDEX ix_staff_1 ON hr.staff (institution_id, employee_code) WHERE (employee_code IS NOT NULL AND deleted_at IS NULL);

