    CONSTRAINT ck_leave_application_day_part CHECK (day_part IN ('full_day', 'forenoon', 'afternoon')),
    CONSTRAINT ck_leave_application_status CHECK (status IN ('pending', 'approved', 'rejected', 'cancelled', 'completed')),
    CONSTRAINT ck_leave_application_1 CHECK (to_at >= from_at),
