-- Intra-module foreign keys
ALTER TABLE hr.staff ADD CONSTRAINT fk_staff_designation_id FOREIGN KEY (designation_id, tenant_id) REFERENCES hr.designation (id, tenant_id) ON DELETE RESTRICT;
