-- === P1-01 / P1-19: leave balances, reporting line ===

CREATE TABLE hr.leave_balance (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    staff_id uuid NOT NULL,
    leave_type_id uuid NOT NULL,
    academic_year_id uuid,
    entitled_days numeric(5,1) NOT NULL,
    used_days numeric(5,1) NOT NULL DEFAULT 0,
    carried_forward_days numeric(5,1) NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_leave_balance PRIMARY KEY (id),
    CONSTRAINT ck_leave_balance_rule CHECK (entitled_days >= 0 AND used_days >= 0 AND carried_forward_days >= 0)
);
COMMENT ON TABLE hr.leave_balance IS 'Leave entitlement and usage for one staff member, leave type and year; updated when applications are approved.';
COMMENT ON COLUMN hr.leave_balance.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN hr.leave_balance.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN hr.leave_balance.staff_id IS 'Staff member.';
COMMENT ON COLUMN hr.leave_balance.leave_type_id IS 'Leave type.';
COMMENT ON COLUMN hr.leave_balance.academic_year_id IS 'Year the balance is tracked for.';
COMMENT ON COLUMN hr.leave_balance.entitled_days IS 'Days granted for the year.';
COMMENT ON COLUMN hr.leave_balance.used_days IS 'Days consumed by approved applications.';
COMMENT ON COLUMN hr.leave_balance.carried_forward_days IS 'Days carried in from the previous year.';
COMMENT ON COLUMN hr.leave_balance.created_at IS 'Row creation time.';
COMMENT ON COLUMN hr.leave_balance.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN hr.leave_balance.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN hr.leave_balance.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN hr.leave_balance.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN hr.leave_balance.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE hr.leave_balance ADD CONSTRAINT fk_leave_balance_staff_id FOREIGN KEY (staff_id, tenant_id) REFERENCES hr.staff (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_leave_balance_staff_id ON hr.leave_balance (staff_id);
ALTER TABLE hr.leave_balance ADD CONSTRAINT fk_leave_balance_leave_type_id FOREIGN KEY (leave_type_id, tenant_id) REFERENCES hr.leave_type (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_leave_balance_leave_type_id ON hr.leave_balance (leave_type_id);
ALTER TABLE hr.staff ADD CONSTRAINT fk_staff_reporting_to_staff_id FOREIGN KEY (reporting_to_staff_id, tenant_id) REFERENCES hr.staff (id, tenant_id) ON DELETE SET NULL (reporting_to_staff_id);
CREATE INDEX ix_staff_reporting_to_staff_id ON hr.staff (reporting_to_staff_id);

-- === P1-16: uniform reference-data shape ===

CREATE UNIQUE INDEX uq_designation_scope_code ON hr.designation (tenant_id, code) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_leave_type_scope_code ON hr.leave_type (institution_id, code) WHERE deleted_at IS NULL;

-- === P1-13: transactional outbox / inbox ===

CREATE TABLE hr.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    publish_error text,
    CONSTRAINT pk_hr_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE hr.outbox_event IS 'Transactional outbox of the hr module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN hr.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN hr.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN hr.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN hr.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN hr.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN hr.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN hr.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN hr.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
COMMENT ON COLUMN hr.outbox_event.publish_error IS 'Why the relay could not turn the row into an event (set aside, not published); NULL otherwise.';
CREATE INDEX ix_hr_outbox_event_pending ON hr.outbox_event (id) WHERE published_at IS NULL AND publish_error IS NULL;
CREATE TABLE hr.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_hr_inbox_event PRIMARY KEY (tenant_id, event_id)
);
COMMENT ON TABLE hr.inbox_event IS 'Inbox of the hr module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN hr.inbox_event.event_id IS 'Global id of the consumed event; recorded per tenant.';
COMMENT ON COLUMN hr.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN hr.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN hr.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN hr.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN hr.inbox_event.processing_error IS 'Last handling error, if any.';
CREATE INDEX ix_hr_inbox_event_processed ON hr.inbox_event (processed_at) WHERE processed_at IS NOT NULL;

-- === P1-15: business uniqueness ignores soft-deleted rows ===

CREATE UNIQUE INDEX uq_leave_balance_1 ON hr.leave_balance (staff_id, leave_type_id, academic_year_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_staff_1 ON hr.staff (institution_id, person_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_staff_2 ON hr.staff (institution_id, user_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_staff_department_1 ON hr.staff_department (staff_id, department_id) WHERE deleted_at IS NULL;

-- === P0-03: row-level security (tenant isolation). The application role is not the table owner and sets app.tenant_id per transaction; a platform-admin role with BYPASSRLS serves cross-tenant operations ===

ALTER TABLE hr.designation ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.designation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.designation USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE hr.inbox_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.inbox_event FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.inbox_event USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE hr.leave_application ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.leave_application FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.leave_application USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE hr.leave_balance ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.leave_balance FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.leave_balance USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE hr.leave_type ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.leave_type FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.leave_type USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE hr.outbox_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.outbox_event FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.outbox_event USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE hr.staff ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.staff FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.staff USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE hr.staff_department ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.staff_department FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.staff_department USING (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- === Module-local infrastructure (distributed deployment: no cross-schema access) ===
CREATE TABLE hr.idempotency_key (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    user_id uuid,
    operation_name varchar(120) NOT NULL,
    request_hash varchar(64),
    response_status smallint,
    response_body text,
    locked_at timestamptz,
    completed_at timestamptz,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_hr_idempotency_key PRIMARY KEY (id),
    CONSTRAINT uq_hr_idempotency_key_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE hr.idempotency_key IS 'Module-local idempotency store of the hr module: stored outcome of a write carrying an Idempotency-Key; replays return the stored response. Rows expire after 24h (cleanup job).';
COMMENT ON COLUMN hr.idempotency_key.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN hr.idempotency_key.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN hr.idempotency_key.idempotency_key IS 'Key sent by the client.';
COMMENT ON COLUMN hr.idempotency_key.user_id IS 'Caller.';
COMMENT ON COLUMN hr.idempotency_key.operation_name IS 'Operation the key was used on.';
COMMENT ON COLUMN hr.idempotency_key.request_hash IS 'Hash of the request body; a replay with a different body is rejected.';
COMMENT ON COLUMN hr.idempotency_key.response_status IS 'Stored HTTP status.';
COMMENT ON COLUMN hr.idempotency_key.response_body IS 'Stored response body.';
COMMENT ON COLUMN hr.idempotency_key.locked_at IS 'Set while the first attempt is still executing.';
COMMENT ON COLUMN hr.idempotency_key.completed_at IS 'When the stored response was written.';
COMMENT ON COLUMN hr.idempotency_key.expires_at IS 'When the row may be purged.';
COMMENT ON COLUMN hr.idempotency_key.created_at IS 'Row creation time.';
COMMENT ON COLUMN hr.idempotency_key.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN hr.idempotency_key.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN hr.idempotency_key.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN hr.idempotency_key.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN hr.idempotency_key.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE hr.idempotency_key ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.idempotency_key FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.idempotency_key USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE hr.operation (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    operation_name varchar(120) NOT NULL,
    resource_type varchar(80),
    resource_id uuid,
    status varchar(20) NOT NULL DEFAULT 'running',
    progress_percent smallint,
    error_code varchar(60),
    error_message varchar(500),
    result_entity_type varchar(80),
    result_entity_id uuid,
    started_by_user_id uuid,
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_hr_operation PRIMARY KEY (id),
    CONSTRAINT ck_hr_operation_status CHECK (status IN ('running', 'succeeded', 'failed', 'cancelled'))
);
COMMENT ON TABLE hr.operation IS 'Module-local long-running operation record of the hr module, returned by its async API calls; polled by clients until it finishes.';
COMMENT ON COLUMN hr.operation.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN hr.operation.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN hr.operation.operation_name IS 'Operation id as exposed by the API (module.Method).';
COMMENT ON COLUMN hr.operation.resource_type IS 'Kind of resource being worked on.';
COMMENT ON COLUMN hr.operation.resource_id IS 'Id of that resource.';
COMMENT ON COLUMN hr.operation.status IS 'running / succeeded / failed / cancelled.';
COMMENT ON COLUMN hr.operation.progress_percent IS 'Progress, when the job reports it.';
COMMENT ON COLUMN hr.operation.error_code IS 'Machine error code when failed.';
COMMENT ON COLUMN hr.operation.error_message IS 'Human error summary when failed.';
COMMENT ON COLUMN hr.operation.result_entity_type IS 'Kind of the produced record.';
COMMENT ON COLUMN hr.operation.result_entity_id IS 'Id of the produced record.';
COMMENT ON COLUMN hr.operation.started_by_user_id IS 'User who started it.';
COMMENT ON COLUMN hr.operation.started_at IS 'Start time.';
COMMENT ON COLUMN hr.operation.finished_at IS 'End time.';
COMMENT ON COLUMN hr.operation.created_at IS 'Row creation time.';
COMMENT ON COLUMN hr.operation.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN hr.operation.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN hr.operation.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN hr.operation.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN hr.operation.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE hr.operation ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.operation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.operation USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE hr.number_sequence (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    sequence_code varchar(40) NOT NULL,
    period_key varchar(20) NOT NULL DEFAULT '',
    prefix varchar(20),
    padding smallint NOT NULL DEFAULT 6,
    next_value bigint NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_hr_number_sequence PRIMARY KEY (id),
    CONSTRAINT uq_hr_number_sequence_1 UNIQUE NULLS NOT DISTINCT (tenant_id, institution_id, sequence_code, period_key)
);
COMMENT ON TABLE hr.number_sequence IS 'Module-local gap-aware number source of the hr module (employee codes). Read with SELECT ... FOR UPDATE inside the issuing transaction; never shared with another module.';
COMMENT ON COLUMN hr.number_sequence.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN hr.number_sequence.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN hr.number_sequence.institution_id IS 'Institution scope (NULL = tenant-wide sequence).';
COMMENT ON COLUMN hr.number_sequence.sequence_code IS 'Which number series of this module (employee codes).';
COMMENT ON COLUMN hr.number_sequence.period_key IS 'Reset period (fiscal year key such as FY2026; empty = never resets).';
COMMENT ON COLUMN hr.number_sequence.prefix IS 'Rendered number prefix.';
COMMENT ON COLUMN hr.number_sequence.padding IS 'Zero padding width of the numeric part.';
COMMENT ON COLUMN hr.number_sequence.next_value IS 'Next number to issue.';
COMMENT ON COLUMN hr.number_sequence.created_at IS 'Row creation time.';
COMMENT ON COLUMN hr.number_sequence.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN hr.number_sequence.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN hr.number_sequence.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN hr.number_sequence.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN hr.number_sequence.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE hr.number_sequence ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.number_sequence FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.number_sequence USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE INDEX ix_number_sequence_institution_id ON hr.number_sequence (institution_id);

-- === Privacy tasks (design PRIVACY-AND-CONSENT-CENTRE §9.1, §10) and the module's scheduled jobs (core JobSchedule) ===
CREATE TABLE hr.privacy_task_receipt (
    task_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    kind varchar(10) NOT NULL,
    payload jsonb NOT NULL,
    status varchar(15) NOT NULL DEFAULT 'received',
    result jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    CONSTRAINT pk_hr_privacy_task_receipt PRIMARY KEY (task_id),
    CONSTRAINT ck_hr_privacy_task_receipt_kind CHECK (kind IN ('task', 'retention')),
    CONSTRAINT ck_hr_privacy_task_receipt_status CHECK (status IN ('received', 'done', 'partial', 'failed',
        'not_applicable')),
    CONSTRAINT ck_hr_privacy_task_receipt_completed CHECK ((status = 'received') = (completed_at IS NULL))
);
COMMENT ON TABLE hr.privacy_task_receipt IS 'The privacy tasks and retention runs privacy sent this module (privacy.rights_request.task_assigned, privacy.retention.due), one row per task or run id: a task dispatched again runs once, is retried after a failure and is answered again from the stored answer (privacy-client PrivacyTaskHandler). Ids, codes and counts only.';
COMMENT ON COLUMN hr.privacy_task_receipt.task_id IS 'The rights-request task id or the retention run id privacy sent; the id the module answers with.';
COMMENT ON COLUMN hr.privacy_task_receipt.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN hr.privacy_task_receipt.kind IS 'task (a rights-request task) or retention (a retention run).';
COMMENT ON COLUMN hr.privacy_task_receipt.payload IS 'The event''s data as privacy sent it: ids, codes and dates only.';
COMMENT ON COLUMN hr.privacy_task_receipt.status IS 'received (waiting for the module''s job), done, partial, failed or not_applicable.';
COMMENT ON COLUMN hr.privacy_task_receipt.result IS 'The answer published (<module>.privacy_task.completed or <module>.privacy_retention.completed): counts and codes; null while received.';
COMMENT ON COLUMN hr.privacy_task_receipt.created_at IS 'When the task or run first arrived.';
COMMENT ON COLUMN hr.privacy_task_receipt.completed_at IS 'When the module answered; null while received.';
CREATE INDEX ix_hr_privacy_task_receipt_received ON hr.privacy_task_receipt (tenant_id, created_at) WHERE status = 'received';
COMMENT ON INDEX hr.ix_hr_privacy_task_receipt_received IS 'The tasks and runs waiting for the module''s job, the oldest first.';
ALTER TABLE hr.privacy_task_receipt ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr.privacy_task_receipt FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr.privacy_task_receipt USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE hr.job_schedule (
    job_code varchar(60) NOT NULL,
    tenant_id uuid NOT NULL,
    next_run_at timestamptz NOT NULL,
    lease_owner uuid,
    lease_until timestamptz,
    last_run_at timestamptz,
    failures integer NOT NULL DEFAULT 0,
    last_error varchar(500),
    CONSTRAINT pk_job_schedule PRIMARY KEY (job_code, tenant_id),
    CONSTRAINT ck_job_schedule_lease CHECK ((lease_owner IS NULL) = (lease_until IS NULL)),
    CONSTRAINT ck_job_schedule_failures CHECK (failures >= 0)
);
COMMENT ON TABLE hr.job_schedule IS 'When each tenant is next due for each scheduled job of the module (core JobSchedule, ROADMAP ARC-4). A tenant is enrolled the first time it has work for the job. Job codes, tenant ids and times only, no personal data, and no row-level security: the job runner claims due rows across tenants, then runs each in its tenant''s own context.';
COMMENT ON COLUMN hr.job_schedule.job_code IS 'The job (<module>.<name>): hr.privacy_tasks (runs the privacy tasks and retention runs of hr.privacy_task_receipt).';
COMMENT ON COLUMN hr.job_schedule.tenant_id IS 'The tenant the job runs for.';
COMMENT ON COLUMN hr.job_schedule.next_run_at IS 'When the tenant is next due.';
COMMENT ON COLUMN hr.job_schedule.lease_owner IS 'The runner (a random id per process) holding the tenant''s run; null while no run is held.';
COMMENT ON COLUMN hr.job_schedule.lease_until IS 'Until when the lease holds; after it another runner may take the run over.';
COMMENT ON COLUMN hr.job_schedule.last_run_at IS 'When the last run ended, finished or failed.';
COMMENT ON COLUMN hr.job_schedule.failures IS 'Failed runs in a row; the retry delay doubles with each.';
COMMENT ON COLUMN hr.job_schedule.last_error IS 'Why the last run failed (exception class and message, first 500 characters); null after a finished run.';
CREATE INDEX ix_job_schedule_due ON hr.job_schedule (next_run_at);
COMMENT ON INDEX hr.ix_job_schedule_due IS 'The due runs, the longest overdue first.';

